fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo (NOT the Ctrl+K search box), choose 'Credentials', then open the 'Audit Log' section. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away. Then walk these sections IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) audit-timeline — confirm the stats cards (Total Events, Successful, Failed, Unique Users) render above a date-grouped timeline (Today / Yesterday / etc.); if events exist, expand one timeline entry via its accordion and confirm it reveals parsed detail rows (e.g. IP Address, Duration, Credential ID); a valid 'No credential access events' empty state alone also counts; (2) audit-filter-toggle — use the toolbar view toggle to switch between Timeline and Table and confirm the layout changes, then open the Filters popover, change the Time range (e.g. Last 24 hours vs Last 30 days) and confirm the event list reloads, and set Status to 'Success' or 'Failed' and confirm the events narrow or a no-match empty state appears. Keep going until every section has been visited.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "audit-timeline",
      "instruction": "verify stats cards + date-grouped timeline with expandable detail",
      "visualCriteria": [
        "Stats cards (Total Events, Successful, Failed, Unique Users) render, and a date-grouped timeline renders (expanding an entry reveals parsed detail fields such as IP Address / Duration / Credential ID) OR a valid 'No credential access events' empty state appears"
      ]
    },
    {
      "name": "audit-filter-toggle",
      "instruction": "switch Timeline/Table and apply time-range + status filters",
      "visualCriteria": [
        "The view toggle switches between Timeline and Table layouts, changing the Time range reloads/updates the event list, and a Status (or Operation) filter narrows the events or shows a no-match empty state"
      ]
    }
  ]
}
